import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {

    static Scanner scanner;
    static PrintWriter writer;
    static Random random = new Random();
    static final int INF = (int) (1e9 + 10), MOD = (int) (998244353);
    static long even, odd;
    static HashMap<Long, Long> cache0;
    static HashMap<Long, Long> cache1;

    static long power(long base, long exp) {
        long result = 1;
        while (exp != 0) {
            if ((exp & 1) != 0) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long compute(long n, int x) {
        if (x == 0) {
            if (cache0.containsKey(n)) {
                return cache0.get(n);
            }
            if (n == 1) {
                long res = even;
                cache0.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * even + odd * odd) % MOD;
                cache0.put(n, res);
                return res;
            }
            long a = compute(n / 2, 0);
            long b = compute(n - n / 2, 0);
            long c = compute(n / 2, 1);
            long d = compute(n - n / 2, 1);
            long res = (a * b + c * d) % MOD;
            cache0.put(n, res);
            return res;
        } else {
            if (cache1.containsKey(n)) {
                return cache1.get(n);
            }
            if (n == 1) {
                long res = odd;
                cache1.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * odd + odd * even) % MOD;
                cache1.put(n, res);
                return res;
            }
            long a = compute(n / 2, 0);
            long b = compute(n - n / 2, 1);
            long c = compute(n / 2, 1);
            long d = compute(n - n / 2, 0);
            long res = (a * b + c * d) % MOD;
            cache1.put(n, res);
            return res;
        }
    }

    static void process() {
        long n = scanner.nextLong();
        long m = scanner.nextLong();
        long l = scanner.nextLong();
        long r = scanner.nextLong();
        long size = n * m;

        if (size % 2 == 0) {
            even = (r - l + 1) / 2;
            if ((r - l) % 2 == 0 && l % 2 == 0) even++;
            odd = r - l + 1 - even;

            cache0 = new HashMap<>();
            cache1 = new HashMap<>();
            writer.println(compute(size, 0));
        } else {
            long answer = power(r - l + 1, size);
            writer.println(answer);
        }
    }

    public static void main(String[] args) {
        scanner = new Scanner(System.in);
        writer = new PrintWriter(System.out);
        int testCases = 1;
        // Uncomment below to read multiple test cases
        // testCases = scanner.nextInt();

        for (int i = 0; i < testCases; i++) {
            process();
        }

        writer.flush();
        writer.close();
    }
}
